import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SetTitle{ActionType: packet.TitleActionSetSubtitle, Text: "hello", FadeInDuration: 10,
#     RemainDuration: 300, FadeOutDuration: -1, XUID: "2535465451234567", PlatformOnlineID: "",
#     FilteredMessage: "hi"}
SUBTITLE = bytes.fromhex("060568656c6c6f14d80401103235333534363534353132333435363700026869")

# generated by gophertunnel b8bd735:
# &packet.SetTitle{ActionType: packet.TitleActionSetDurations, FadeInDuration: -1, RemainDuration: 64,
#     FadeOutDuration: 1000}
DURATIONS = bytes.fromhex("0a00018001d00f000000")

GOLDENS = [
    pytest.param(
        v2225.SetTitlePacket(
            type=v2225.SetTitlePacket.TitleType.SUBTITLE,
            title_text="hello",
            fade_in_time=10,
            stay_time=300,
            fade_out_time=-1,
            xuid="2535465451234567",
            platform_online_id="",
            filtered_title_text="hi",
        ),
        SUBTITLE,
        id="subtitle",
    ),
    pytest.param(
        v2225.SetTitlePacket(
            type=v2225.SetTitlePacket.TitleType.TIMES, fade_in_time=-1, stay_time=64, fade_out_time=1000
        ),
        DURATIONS,
        id="durations",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_set_title_is_packet_88(version):
    assert version.packets[88] is version.SetTitlePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_title_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_title_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
